    AccountMeta::new(forged_key, false),
    AccountMeta::new(real_key, false),
];
let ix_attack = env.raw_ix(&ix_data, metas_attack);
let contas_attack = vec![
    (forged_key, forged_account.clone()),
    (real_key, real_account.clone()),
];
let r = env.attack("burn com ledger forjado (owner != programa)", &ix_attack, &contas_attack);

if r.program_result == ProgramResult::Success {
    let after_real = after(&r, &real_key).data();
    let new_supply = read_u64(after_real, 40);
    let new_balance = read_u64(after_real, 48);
    env.effect("programa gravou supply decrementado na conta real a partir de dados da conta forjada", new_supply == 900);
    env.effect("programa gravou balance decrementado na conta real a partir de dados da conta forjada", new_balance == 400);
}"}

